const DogZoom: React.FC<DogZoomProps> = ({
  backgroundColor = "#FFF2E0",
  transparentBackground = false,
  durationInSeconds = 12,
  primaryDogColor = "#F4A261",
  patternColors = ["#F4A261", "#E76F51", "#E9C46A", "#DDBEA9", "#A5A58D", "#B5838D"],
  wagsPerSecond = 2,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Generate a massive 41x41 grid (1681 dogs) deterministically once
  const GRID_SIZE = 41;
  const dogs = useMemo(() => {
    const arr: GridDog[] = [];
    const centerIdx = Math.floor(GRID_SIZE / 2); // 20

    for (let r = 0; r < GRID_SIZE; r++) {
      for (let c = 0; c < GRID_SIZE; c++) {
        const isCenter = r === centerIdx && c === centerIdx;
        const seed = r * 1000 + c;

        arr.push({
          id: seed,
          r,
          c,
          isCenter,
          color: isCenter
            ? primaryDogColor
            : patternColors[Math.floor(random(seed) * patternColors.length)],
          earType: isCenter ? "floppy" : random(seed + 1) > 0.5 ? "floppy" : "pointy",
          headTilt: isCenter ? 0 : random(seed + 2) * 30 - 15,
          hasTongue: isCenter ? true : random(seed + 3) > 0.7,
          tailPhase: random(seed + 4) * Math.PI * 2,
          scaleOffset: isCenter ? 1.05 : random(seed + 5) * 0.2 + 0.85,
        });
      }
    }
    return arr;
  }, [primaryDogColor, patternColors]);

  // Timing logic for the smooth exponential zoom out
  const zoomStartFrame = fps * 1.5; // Hold tight on center dog for 1.5s
  const zoomEndFrame = durationInSeconds * fps - fps * 1.5; // Arrive at full grid 1.5s before end

  // Camera constraints
  const DOG_CELL_SIZE = 200;
  const maxScale = Math.min(width, height) / DOG_CELL_SIZE * 0.85; // Zoomed in: dog fits nicely in view
  
  // Adaptive minScale to support 9:16 portrait canvas perfectly by scaling to the maximum screen dimension
  const minScale = Math.max(width, height) / (GRID_SIZE * DOG_CELL_SIZE * 0.95); // Zoomed out: entire grid fills screen nicely

  // Logarithmic interpolation for constant perceptual zoom speed
  const scaleLog = interpolate(
    frame,
    [zoomStartFrame, zoomEndFrame],
    [Math.log(maxScale), Math.log(minScale)],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.inOut(Easing.cubic),
    }
  );
  const currentScale = Math.exp(scaleLog);

  // SVG viewBox math to act as a 2D camera
  const viewableWidth = width / currentScale;
  const viewableHeight = height / currentScale;
  
  // Center point of the entire grid in SVG coordinates
  const gridCenterX = (GRID_SIZE * DOG_CELL_SIZE) / 2;
  const gridCenterY = (GRID_SIZE * DOG_CELL_SIZE) / 2;
  
  const minX = gridCenterX - viewableWidth / 2;
  const minY = gridCenterY - viewableHeight / 2;
  const viewBox = `${minX} ${minY} ${viewableWidth} ${viewableHeight}`;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      <svg
        width={width}
        height={height}
        viewBox={viewBox}
        style={{ width: "100%", height: "100%", transition: "none" }}
      >
        {dogs.map((dog) => (
          <DogGraphic
            key={dog.id}
            data={dog}
            frame={frame}
            fps={fps}
            wagsPerSecond={wagsPerSecond}
          />
        ))}
      </svg>
    </AbsoluteFill>
  );
};

export default DogZoom;